#!/bin/zsh
# 文字稿逐句回听：点一句跳回音频、当前句高亮、单句循环，适合听播客学英语。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音转成文字、整理成纪要）。浅色模式。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、选中状态）；绝对不要蓝色、紫色、青色、彩虹色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_listen "【录音详情 · 文字稿页签 · 逐句回听】一个 macOS 窗口宽约 1260：左边窄侧栏（豆仓、开始录音、总览/录音/素材/语音输入/知识库），中间录音列表（选中一条「6 Minute English · Learning from different generations」，来源小胶囊「(链接图标) Apple 播客」），右边详情：顶部元信息「(话筒图标) 播客 · Apple 播客 · 7 分钟」，大标题「Learning from different generations」，分段控件「纪要 / 文字稿（选中）/ 改写」。文字稿页签下：顶上一条细工具条，左边「双语 / 原文 / 译文」小分段控件，右边几个小控件：「(循环箭头) 单句循环」开关（开着，玫瑰红）、「(上箭头) 上一句」「(下箭头) 下一句」两个小图标按钮、「0.8x」倍速胶囊、一个小灰字提示「点一句就从那里播 · 空格 暂停 · R 再听这句」。下面是逐句文字稿：每句一行，左边灰色时间「00:42」，右边英文句子，句子下面一行灰色小字中文译文。**正在播放的那句**整行浅玫瑰红底（#FFF1F2）、左边一条 3px 玫瑰红竖线、文字是深色，句尾有一个小的「(循环箭头) 第 2 遍」标签；其它句子文字是灰色的。鼠标停在另一句上时，那一行浅暖灰底，右侧浮出两个小图标按钮「▶ 从这句播」「↻ 这句再听」。窗口底部是播放条：玫瑰红圆形播放按钮、后退 15 秒 / 前进 15 秒、波形进度条（当前句那一小段在波形上用浅玫瑰红高亮）、时间「0:42 / 6:51」、「0.8x」。整体克制，像 Apple 播客的歌词逐句高亮。$S"
